package com.crm.invoice.entity;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;
@Entity @Table(name="invoice_documents") @Data public class InvoiceDocument {@Id @Column(name="invoice_id") private Long invoiceId;@Column(name="presentation_id",nullable=false,updatable=false) private Long presentationId;@Lob @Column(nullable=false,updatable=false,columnDefinition="LONGBLOB") private byte[] content;@Column(nullable=false,length=64,updatable=false) private String digest;@Column(name="created_by",nullable=false,updatable=false) private Long createdBy;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}}
